(() => {
"use strict";
const KEY="also-crm-intelligence-fixed-v1";const LOG_KEY="also-crm-intelligence-log";
const DEFAULT_AZURE={endpoint:"",deployment:"",apiVersion:"2025-04-01-preview",apiKey:"",status:{state:"none",message:""}};
function DEFAULT_PORTALS(){return[{id:"website",name:"Firmen-Website",type:"website",url:"",enabled:true},{id:"companyhouse",name:"CompanyHouse (Gratis-Profile)",type:"search",url:"https://www.companyhouse.de/search?query={q}",enabled:false},{id:"firmenwissen",name:"Firmenwissen (Kurzprofile, gratis)",type:"search",url:"https://www.firmenwissen.de/kurzprofile_suche.html?query={q}",enabled:false},{id:"evidat",name:"Evidat",type:"search",url:"https://www.evidat.de/?s={q}",enabled:false},{id:"genios",name:"Genios Firmen",type:"search",url:"https://www.genios.de/dosearch?requestText={q}",enabled:false},{id:"northdata",name:"Northdata (Gratis-Basisprofil)",type:"search",url:"https://www.northdata.de/?query={q}",enabled:true},{id:"opencorporates",name:"OpenCorporates (offen/gratis)",type:"search",url:"https://opencorporates.com/companies?q={q}",enabled:true},{id:"dealfront",name:"Dealfront (Echobot/Leadfeeder)",type:"search",url:"https://www.dealfront.com/?q={q}",enabled:false},{id:"unternehmensregister",name:"unternehmensregister.de",type:"search",url:"https://www.unternehmensregister.de/ureg/result.html;?submitaction=showDocuments&suchTyp=n&nameOderFirma={q}",enabled:true},{id:"bundesanzeiger",name:"bundesanzeiger.de (freie Suche)",type:"search",url:"https://www.bundesanzeiger.de/pub/de/suchen2?4=&fulltext={q}",enabled:true}]}
const DEFAULT_SETTINGS={crawlPortals:DEFAULT_PORTALS(),corsProxy:"",maxChars:6000};
const TAG_MAP={
 manufacturers:{HP:["hp","hewlett packard","hp inc"],Canon:["canon"],Epson:["epson"],Ricoh:["ricoh"],Xerox:["xerox"],Lenovo:["lenovo"],Dell:["dell"],Cisco:["cisco"],Fortinet:["fortinet"],Sophos:["sophos"],Microsoft:["microsoft"]},
 technologies:{Azure:["azure"],"Microsoft 365":["microsoft 365","office 365","m365"],Teams:["teams"],Intune:["intune"],VMware:["vmware"],Veeam:["veeam"],"Endpoint Security":["endpoint security"],Firewall:["firewall"]},
 business_areas:{"Managed Services":["managed services","managed service","msp"],"Managed Print Services":["managed print","print management","output management"],"Cloud Services":["cloud services","cloud computing"],"IT Security":["it security","cyber security","security"],"Document Management":["document management"],"Networking":["networking","network"]}
};
const CLUSTERS=[
 {id:"cloud",name:"Microsoft Cloud Zielkunden",all:["Microsoft"],any:["Azure","Microsoft 365","Cloud Services","Managed Services"]},
 {id:"print",name:"Managed Print Zielkunden",all:[],any:["HP","Canon","Epson","Ricoh","Managed Print Services","Document Management"]},
 {id:"security",name:"Security Zielkunden",all:[],any:["Fortinet","Sophos","Cisco","Firewall","Endpoint Security","IT Security"]},
 {id:"workplace",name:"Modern Workplace Zielkunden",all:["Microsoft"],any:["Microsoft 365","Teams","Intune","Managed Services"]}
];
let state=loadState(), view="dashboard", selected=null, logLines=loadLog();
function loadState(){try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.companies))return hydrate(s)}catch(e){}return hydrate({companies:[],azure:DEFAULT_AZURE,createdAt:Date.now()})}
function hydrate(s){s.azure=Object.assign({},DEFAULT_AZURE,s.azure||{});s.azure.status=Object.assign({state:"none",message:""},s.azure.status||{});s.settings=Object.assign({},DEFAULT_SETTINGS,s.settings||{});if(!Array.isArray(s.settings.crawlPortals)||!s.settings.crawlPortals.length)s.settings.crawlPortals=DEFAULT_PORTALS();s.companies=(s.companies||[]).map(normalizeCompany);return s}
function normalizeCompany(c){return Object.assign({company_id:"",company_name:"",website_url:"",legal_form:"",industry:"",nace_code:"",nace_label:"",employee_range:"",city:"",country:"",crm_revenue:0,raw_tags:[],tags:{manufacturers:[],technologies:[],business_areas:[]},evidence:[],crawl_status:"pending",last_crawled_at:"",opportunity_score:0,priority:"D",clusters:[],notes:"",source_text:"",ai_summary:"",ai_potential:"",firmographics:{}},c,{raw_tags:Array.isArray(c.raw_tags)?c.raw_tags:[],tags:Object.assign({manufacturers:[],technologies:[],business_areas:[]},c.tags||{}),evidence:Array.isArray(c.evidence)?c.evidence:[],firmographics:(c.firmographics&&typeof c.firmographics==="object")?c.firmographics:{}})}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function loadLog(){try{const a=JSON.parse(localStorage.getItem(LOG_KEY));if(Array.isArray(a))return a}catch(e){}return[]}
function saveLog(){try{localStorage.setItem(LOG_KEY,JSON.stringify(logLines.slice(-500)))}catch(e){}}
function azureCtx(){const a=state.azure||{};let host="";try{host=a.endpoint?new URL(/^https?:\/\//i.test(a.endpoint)?a.endpoint:"https://"+a.endpoint).host:""}catch(e){host=String(a.endpoint||"")}return{endpointHost:host,deployment:a.deployment||"",apiVersion:a.apiVersion||"",apiKeyPresent:!!a.apiKey,apiKeyLength:a.apiKey?a.apiKey.length:0,url:buildAzureUrl(a)}}
function logHeader(){const c=azureCtx();return["# ALSO CRM Intelligence — Diagnose-Logfile","# Erstellt: "+new Date().toISOString(),"# App: "+(document.title||"")+" · Protokoll: "+location.protocol,"# UserAgent: "+navigator.userAgent,"# Azure-Kontext (ohne API-Schlüssel):","#   endpointHost = "+c.endpointHost,"#   deployment   = "+c.deployment,"#   apiVersion   = "+c.apiVersion,"#   apiKey       = "+(c.apiKeyPresent?("vorhanden, Länge "+c.apiKeyLength):"FEHLT"),"#   Request-URL  = "+(c.url||"(unvollständig)"),"#   Status       = "+((state.azure&&state.azure.status&&state.azure.status.state)||"none"),"# "+"-".repeat(60),""].join("\n")}
function esc(v){return String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}
function toast(msg){const e=document.querySelector("#toast");e.textContent=msg;e.classList.remove("hidden");setTimeout(()=>e.classList.add("hidden"),3000)}
function badge(v){let c="gray-b";const x=String(v||"").toLowerCase();if(["a","high","success","successfully crawled","connected","ok","hoch"].includes(x))c="green-b";if(["b","medium","testing","in arbeit"].includes(x))c="amber-b";if(["c","d","low","failed","error","pending"].includes(x))c="red-b";if(x.includes("azure")||x.includes("technology"))c="blue-b";return `<span class="badge ${c}">${esc(v||"–")}</span>`}
function tags(c){return [...c.tags.manufacturers,...c.tags.technologies,...c.tags.business_areas]}
function allTags(){const m=new Map();state.companies.forEach(c=>tags(c).forEach(t=>m.set(t,(m.get(t)||0)+1)));return [...m.entries()].sort((a,b)=>b[1]-a[1])}
function score(c){let s=0;s+=Math.min(25,Number(c.crm_revenue||0)/20000);s+=Math.min(20,tags(c).length*3);s+=c.website_url?15:0;s+=c.nace_code?10:0;s+=c.employee_range?10:0;s+=c.crawl_status==="success"?20:0;return Math.min(100,Math.round(s))}
function priority(s){return s>=75?"A":s>=55?"B":s>=35?"C":"D"}
function evidence(text,term,source="Mock website"){return {term,source_url:source,evidence:text.slice(0,240),confidence:0.86}}
function crawlCompany(c){const base=(c.company_name+" "+c.industry+" "+c.raw_tags.join(" ")+" "+(c.website_url||"")).toLowerCase();const result={manufacturers:[],technologies:[],business_areas:[]},ev=[];for(const group of Object.keys(TAG_MAP))for(const [canon,terms] of Object.entries(TAG_MAP[group])){const hit=terms.find(t=>base.includes(t));if(hit){result[group].push(canon);ev.push(evidence(`Treffer „${hit}“ im CRM-/Website-Kontext.`,hit,c.website_url||"CRM"))}}Object.keys(result).forEach(k=>result[k]=[...new Set(result[k])]);c.tags=result;c.evidence=ev;c.crawl_status="success";c.last_crawled_at=new Date().toISOString();c.opportunity_score=score(c);c.priority=priority(c.opportunity_score);c.clusters=matchClusters(c);save();return c}
function stripHtml(h){return String(h||"").replace(/<script[\s\S]*?<\/script>/gi," ").replace(/<style[\s\S]*?<\/style>/gi," ").replace(/<[^>]+>/g," ").replace(/&nbsp;/gi," ").replace(/&amp;/gi,"&").replace(/&lt;/gi,"<").replace(/&gt;/gi,">").replace(/\s+/g," ").trim()}
function extractJson(t){if(!t)return null;try{return JSON.parse(t)}catch(e){}const m=String(t).match(/\{[\s\S]*\}/);if(m){try{return JSON.parse(m[0])}catch(e){}}return null}
function TAG_VOCAB(){return{manufacturers:Object.keys(TAG_MAP.manufacturers),technologies:Object.keys(TAG_MAP.technologies),business_areas:Object.keys(TAG_MAP.business_areas)}}
function portalUrl(p,c){if(!p)return"";if(p.type==="website")return String(c.website_url||"").trim();const q=encodeURIComponent(c.company_name||"");let dom="";try{dom=c.website_url?new URL(/^https?:\/\//i.test(c.website_url)?c.website_url:"https://"+c.website_url).host:""}catch(e){}return String(p.url||"").replace(/\{q\}/g,q).replace(/\{domain\}/g,encodeURIComponent(dom))}
async function fetchPageText(url){if(!/^https?:\/\//i.test(url||""))return{ok:false,error:"keine http(s)-URL"};const proxy=((state.settings&&state.settings.corsProxy)||"").trim();const target=proxy?proxy+encodeURIComponent(url):url;try{const r=await fetch(target,{redirect:"follow"});if(!r.ok)return{ok:false,error:"HTTP "+r.status};const html=await r.text();return{ok:true,text:stripHtml(html)}}catch(e){return{ok:false,error:e.message||String(e)}}}
async function gatherSources(c){const portals=((state.settings&&state.settings.crawlPortals)||[]).filter(p=>p.enabled);const max=(state.settings&&state.settings.maxChars)||6000;const parts=[],used=[];for(const p of portals){const u=portalUrl(p,c);if(!u){log("INFO","crawl_skip_portal",{portal:p.id,reason:"keine URL"});continue}const f=await fetchPageText(u);if(f.ok&&f.text){parts.push("### Quelle: "+p.name+" ("+u+")\n"+f.text.slice(0,max));used.push({portal:p.id,url:u,chars:f.text.length});log("INFO","crawl_fetch_ok",{portal:p.id,url:u,chars:f.text.length})}else{log("WARN","crawl_fetch_failed",{portal:p.id,url:u,error:f.error})}}if(c.source_text&&c.source_text.trim()){parts.push("### Quelle: Manueller Text\n"+stripHtml(c.source_text).slice(0,max));used.push({portal:"manual",chars:c.source_text.length})}return{text:parts.join("\n\n").slice(0,max*2),used}}
function applyAIResult(c,p,fallbackSource){const v=TAG_VOCAB();const pick=(arr,allow)=>Array.isArray(arr)?[...new Set(arr.map(x=>String(x)).filter(x=>allow.includes(x)))]:[];c.tags={manufacturers:pick(p.manufacturers,v.manufacturers),technologies:pick(p.technologies,v.technologies),business_areas:pick(p.business_areas,v.business_areas)};const ev=[];if(Array.isArray(p.evidence))p.evidence.forEach(e=>{if(e&&e.term)ev.push({term:String(e.term).slice(0,80),source_url:String(e.source_url||fallbackSource||"KI").slice(0,300),evidence:String(e.evidence||"").slice(0,240),confidence:Math.max(0,Math.min(1,Number(e.confidence)||0.7))})});if(Array.isArray(p.signals))p.signals.forEach(s=>{const term=typeof s==="string"?s:(s&&s.term);if(term)ev.push({term:String(term).slice(0,80),source_url:fallbackSource||"KI-Signal",evidence:"KI-Signal",confidence:0.6})});c.evidence=ev;if(p.nace_code&&!c.nace_code)c.nace_code=String(p.nace_code).slice(0,12);if(p.nace_label&&!c.nace_label)c.nace_label=String(p.nace_label).slice(0,140);c.ai_summary=p.summary?String(p.summary).slice(0,800):"";c.ai_potential=p.potential?String(p.potential).slice(0,12).toLowerCase():"";const fg=(p.firmographics&&typeof p.firmographics==="object")?p.firmographics:{};c.firmographics={employees:sfx(fg.employees,40),employee_range:sfx(fg.employee_range,60),revenue:sfx(fg.revenue,60),locations:sfx(fg.locations,40),location_countries:Array.isArray(fg.location_countries)?fg.location_countries.map(x=>sfx(x,40)).filter(Boolean).slice(0,25):sfx(fg.location_countries,160),founded_year:sfx(fg.founded_year,10),legal_form:sfx(fg.legal_form,60),hq_city:sfx(fg.hq_city,80),hq_country:sfx(fg.hq_country,60),industry:sfx(fg.industry,120)};if(!c.employee_range&&c.firmographics.employee_range)c.employee_range=c.firmographics.employee_range;if(!c.legal_form&&c.firmographics.legal_form)c.legal_form=c.firmographics.legal_form;if(!c.city&&c.firmographics.hq_city)c.city=c.firmographics.hq_city;if(!c.country&&c.firmographics.hq_country)c.country=c.firmographics.hq_country;if(!c.industry&&c.firmographics.industry)c.industry=c.firmographics.industry;if((!c.crm_revenue||c.crm_revenue===0)&&c.firmographics.revenue){const rv=parseRevenue(c.firmographics.revenue);if(rv>0)c.crm_revenue=rv}}
function localSummary(c){const s=c.opportunity_score,terms=(c.raw_tags||[]),t=tags(c);const lvl=s>=75?"sehr hoch":s>=55?"hoch":s>=35?"mittel":"eher niedrig";const found=t.length?("Gefunden wurden u. a.: "+t.slice(0,8).join(", ")+"."):"Es wurden noch keine belastbaren Signale gefunden.";const base=terms.length?("Bezogen auf die Suchbegriffe „"+terms.join("“, „")+"“ ist das Potenzial "+lvl+" (Score "+s+"/100, Prioritaet "+c.priority+")."):("Das Potenzial ist "+lvl+" (Score "+s+"/100, Prioritaet "+c.priority+"). Es sind keine Suchbegriffe hinterlegt.");return base+" "+found}
function setAIResult(c){state.aiResult={company_id:c.company_id,name:c.company_name,summary:c.ai_summary||localSummary(c),potential:c.ai_potential||(c.opportunity_score>=55?"hoch":c.opportunity_score>=35?"mittel":"niedrig"),score:c.opportunity_score,priority:c.priority,terms:c.raw_tags||[],tags:tags(c),firmographics:c.firmographics||{},stammdaten:buildStammdaten(c)}}
function formatEuro(n){n=Number(n)||0;if(!n)return"";return n.toLocaleString("de-DE")+" €"}
function buildStammdaten(c){const fg=c.firmographics||{};const lc=Array.isArray(fg.location_countries)?fg.location_countries.join(", "):(fg.location_countries||"");return {groesse:fg.employee_range||c.employee_range||"",mitarbeiter:fg.employees||"",umsatz:fg.revenue||(c.crm_revenue?formatEuro(c.crm_revenue):""),niederlassungen:fg.locations||"",laender:lc||fg.hq_country||c.country||"",gruendung:fg.founded_year||"",rechtsform:fg.legal_form||c.legal_form||"",hauptsitz:[fg.hq_city||c.city,fg.hq_country||c.country].filter(Boolean).join(", "),branche:fg.industry||c.industry||"",nace:c.nace_code||""}}
function stammdatenHtml(sd){if(!sd)return"";const rows=[["Unternehmensgröße",sd.groesse],["Mitarbeiterzahl",sd.mitarbeiter],["Jahresumsatz",sd.umsatz],["Niederlassungen",sd.niederlassungen],["Länder",sd.laender],["Hauptsitz",sd.hauptsitz],["Rechtsform",sd.rechtsform],["Gründungsjahr",sd.gruendung],["Branche",sd.branche],["NACE",sd.nace]];const known=[sd.groesse,sd.mitarbeiter,sd.umsatz,sd.niederlassungen].some(Boolean);const body=rows.map(r=>'<div class="split" style="border-bottom:1px solid var(--line);padding:5px 0"><span class="muted">'+esc(r[0])+'</span><b>'+(r[1]?esc(r[1]):'<span class="muted">unbekannt</span>')+'</b></div>').join("");const hint=known?"":'<p class="muted" style="margin-top:6px">Noch keine Unternehmensdaten gewonnen. Pruefe die Azure-Verbindung (HTTP 401?) oder hinterlege einen Website-/Quelltext bzw. aktiviere ein Crawling-Portal.</p>';return '<div style="margin-top:14px"><h4 style="margin:0 0 6px">Gewonnene Stammdaten</h4><div class="grid grid-2">'+body+'</div>'+hint+'</div>'}
function sfx(v,n){return v==null?"":String(v).slice(0,n||120)}
function parseRevenue(s){if(s==null)return 0;if(typeof s==="number")return s;let t=String(s).toLowerCase().replace(/[.\s]/g,"").replace(/,/g,".");const m=t.match(/([0-9]+(?:\.[0-9]+)?)/);if(!m)return 0;let n=parseFloat(m[1]);if(/mrd|milliard|bn|billion/.test(t))n*=1e9;else if(/mio|million/.test(t)||/[0-9]m(?![a-z])/.test(t))n*=1e6;else if(/tsd|tausend/.test(t)||/[0-9]k(?![a-z])/.test(t))n*=1e3;return Math.round(n)}
function fgHtml(fg){if(!fg)return"";const rows=[["Mitarbeiterzahl",fg.employees],["Unternehmensgröße",fg.employee_range],["Jahresumsatz",fg.revenue],["Niederlassungen",fg.locations],["Gründungsjahr",fg.founded_year],["Rechtsform",fg.legal_form],["Hauptsitz",[fg.hq_city,fg.hq_country].filter(Boolean).join(", ")],["Branche",fg.industry]].filter(r=>r[1]);if(!rows.length)return"";return '<div style="margin-top:10px"><small class="muted">Firmographics (Vertrieb):</small><div class="grid grid-2" style="margin-top:6px">'+rows.map(r=>'<div class="split" style="border-bottom:1px solid var(--line);padding:4px 0"><span class="muted">'+esc(r[0])+'</span><b>'+esc(r[1])+'</b></div>').join("")+'</div></div>'}
async function analyzeCompanyAI(c){const a=state.azure;if(!a.endpoint||!a.deployment||!a.apiKey)throw new Error("Azure nicht konfiguriert");const src=await gatherSources(c);const v=TAG_VOCAB();const sys="Du bist ein Analyst, der Firmen für die CRM-Anreicherung eines IT-Distributors klassifiziert. Antworte AUSSCHLIESSLICH mit einem JSON-Objekt (kein Fließtext) nach dem Schema {\"manufacturers\":[],\"technologies\":[],\"business_areas\":[],\"nace_code\":\"\",\"nace_label\":\"\",\"signals\":[],\"evidence\":[{\"term\":\"\",\"source_url\":\"\",\"evidence\":\"\",\"confidence\":0.0}],\"firmographics\":{\"employees\":\"\",\"employee_range\":\"\",\"revenue\":\"\",\"locations\":\"\",\"location_countries\":[],\"founded_year\":\"\",\"legal_form\":\"\",\"hq_city\":\"\",\"hq_country\":\"\",\"industry\":\"\"},\"potential\":\"hoch|mittel|niedrig\",\"summary\":\"\"}. Die Felder manufacturers, technologies und business_areas duerfen NUR Werte aus den jeweils erlaubten Listen enthalten. signals sind freie Kaufsignale/Hinweise (z. B. Ausschreibungen, Wachstum, Rollouts). Jeder Tag in evidence braucht einen kurzen Textbeleg, die Quelle und eine confidence zwischen 0 und 1. potential ist genau einer der Werte hoch, mittel oder niedrig. summary ist eine umgangssprachliche deutsche Einschaetzung in 2-4 Saetzen, wie hoch das Vertriebspotenzial bezogen auf die genannten CRM-Suchbegriffe ist. In firmographics erfasst du alle vertriebsrelevanten Firmendaten aus dem Quelltext: Mitarbeiterzahl (employees), Groessenklasse (employee_range), Jahresumsatz (revenue, z. B. 12 Mio. EUR), Anzahl Niederlassungen/Standorte (locations) und in welchen Laendern (location_countries als Liste von Laendernamen), Gruendungsjahr (founded_year), Rechtsform (legal_form), Hauptsitz (hq_city/hq_country) und Branche (industry). Nur belegbare Werte, sonst Feld leer lassen. Erfinde nichts: nur was aus dem Kontext hervorgeht.";const usr="Erlaubte Hersteller: "+v.manufacturers.join(", ")+"\nErlaubte Technologien: "+v.technologies.join(", ")+"\nErlaubte Geschaeftsfelder: "+v.business_areas.join(", ")+"\n\nFirmendaten:\nName: "+(c.company_name||"")+"\nBranche: "+(c.industry||"")+"\nOrt: "+(c.city||"")+" "+(c.country||"")+"\nBekannte Firmendaten: Mitarbeiterklasse "+(c.employee_range||"?")+", Umsatz "+(c.crm_revenue||"?")+"\nCRM-Suchbegriffe: "+((c.raw_tags||[]).join(", "))+"\nWebsite: "+(c.website_url||"")+"\n\nRecherchierter Quelltext:\n"+(src.text||"(kein externer Text verfuegbar - nur die CRM-Felder nutzen)");const out=await azureChat([{role:"system",content:sys},{role:"user",content:usr}],{maxTokens:1400,jsonMode:true});const parsed=extractJson(out);if(!parsed)throw new Error("KI-Antwort nicht als JSON lesbar");applyAIResult(c,parsed,(src.used[0]&&src.used[0].url)||c.website_url||"KI");c.crawl_status="success";c.last_crawled_at=new Date().toISOString();c.opportunity_score=score(c);c.priority=priority(c.opportunity_score);c.clusters=matchClusters(c);setAIResult(c);save();log("INFO","ai_analysis_ok",{company:c.company_id,sources:src.used.length,tags:tags(c).length,potential:c.ai_potential});return{sources:src.used}}
function matchClusters(c){const ts=new Set(tags(c));return CLUSTERS.filter(x=>x.all.every(t=>ts.has(t))&&(x.any.length===0||x.any.some(t=>ts.has(t)))).map(x=>x.name)}
function importSample(){fetch("data/sample_companies.json").then(r=>r.json()).then(rows=>{state.companies=rows.map(normalizeCompany);save();render();toast("Beispieldaten geladen")}).catch(()=>toast("Beispieldaten konnten bei file:// nicht geladen werden. JSON-Import verwenden."))}
function page(title,sub,body,actions=""){return `<section class="main"><div class="page-head"><div><h2>${title}</h2><div class="muted">${sub}</div></div><div class="toolbar">${actions}</div></div>${body}</section>`}
function dashboard(){const cs=state.companies, crawled=cs.filter(c=>c.crawl_status==="success").length, avg=cs.length?Math.round(cs.reduce((a,c)=>a+c.opportunity_score,0)/cs.length):0;return page("Dashboard","Übersicht über CRM-Anreicherung, Tags und Vertriebschancen",`<div class="grid grid-4"><div class="card kpi">CRM-Unternehmen<b>${cs.length}</b><small>importiert / erfasst</small></div><div class="card kpi">Crawls erfolgreich<b>${crawled}</b><small>von ${cs.length}</small></div><div class="card kpi">Ø Opportunity Score<b>${avg}</b><small>von 100</small></div><div class="card kpi">CRM Cluster<b>${CLUSTERS.length}</b><small>regelbasiert aktiv</small></div></div><div class="grid grid-2" style="margin-top:14px"><div class="panel"><div class="split"><h3>Top-Tags</h3><button class="btn green" data-action="crawlAll">Alle crawlen</button></div>${allTags().slice(0,12).map(([t,n])=>`<div style="margin:12px 0"><div class="split"><span>${esc(t)}</span><b>${n}</b></div><div class="bar"><i style="width:${cs.length?Math.round(n/cs.length*100):0}%"></i></div></div>`).join("")||'<div class="empty">Noch keine Tags vorhanden.</div>'}</div><div class="panel"><h3>Prioritäten</h3>${["A","B","C","D"].map(p=>{const n=cs.filter(c=>c.priority===p).length;return `<div class="split" style="padding:13px 0;border-bottom:1px solid var(--line)">${badge(p)}<b>${n} Unternehmen</b></div>`}).join("")}</div></div>`)}
function companies(){const q=(document.querySelector("#companySearch")?.value||"").toLowerCase();const rows=state.companies.filter(c=>(c.company_name+" "+c.company_id+" "+c.industry+" "+tags(c).join(" ")).toLowerCase().includes(q));return page("Unternehmen","CRM-Stammdaten bearbeiten, analysieren und crawlen",`<div class="toolbar"><input id="companySearch" class="search" placeholder="Unternehmen, Branche oder Tag suchen" value="${esc(q)}" oninput="render()"><select id="priorityFilter" onchange="render()"><option value="">Alle Prioritäten</option>${["A","B","C","D"].map(x=>`<option ${document.querySelector("#priorityFilter")?.value===x?"selected":""}>${x}</option>`).join("")}</select></div>${state.aiResult?`<div class="panel" style="margin-top:14px"><div class="split"><h3>KI-Auswertung: ${esc(state.aiResult.name)}</h3><button class="btn" data-action="closeAI">×</button></div><div style="margin:10px 0">${badge("Potenzial: "+state.aiResult.potential)} <b>Score ${state.aiResult.score}/100</b> · Priorität ${badge(state.aiResult.priority)}</div><p style="line-height:1.5">${esc(state.aiResult.summary)}</p><div style="margin-top:8px"><small class="muted">Ausgewertete Suchbegriffe:</small><br>${(state.aiResult.terms||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join("")||'<span class="muted">keine hinterlegt</span>'}</div>${(state.aiResult.tags&&state.aiResult.tags.length)?`<div style="margin-top:8px"><small class="muted">Erkannte Tags:</small><br>${state.aiResult.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join("")}</div>`:""}${stammdatenHtml(state.aiResult.stammdaten)}</div>`:""}<div class="panel table-wrap" style="margin-top:14px"><table class="table"><tr><th>Unternehmen</th><th>Branche / NACE</th><th>Tags</th><th>Score</th><th>Priorität</th><th>Status</th><th>Aktionen</th></tr>${rows.filter(c=>{const f=document.querySelector("#priorityFilter")?.value;return !f||c.priority===f}).map(c=>`<tr><td><b>${esc(c.company_name)}</b><div class="muted">${esc(c.company_id)} · ${esc(c.city)}</div></td><td>${esc(c.industry)}<div class="muted">${esc(c.nace_code)}</div></td><td>${tags(c).slice(0,7).map(t=>`<span class="tag">${esc(t)}</span>`).join("")}</td><td><b>${c.opportunity_score}</b></td><td>${badge(c.priority)}</td><td>${badge(c.crawl_status)}</td><td><div class="toolbar"><button class="btn primary" data-ai="${esc(c.company_id)}">KI-Analyse</button><button class="btn green" data-crawl="${esc(c.company_id)}">Crawlen</button><button class="btn" data-edit="${esc(c.company_id)}">Bearbeiten</button><button class="btn danger" data-delete="${esc(c.company_id)}">Löschen</button></div></td></tr>`).join("")||'<tr><td colspan="7" class="empty">Keine Unternehmen gefunden.</td></tr>'}</table></div>`,"<button class=\"btn\" data-action=\"crawlAllAI\">KI: Alle analysieren</button><button class=\"btn primary\" data-action=\"add\">+ Unternehmen hinzufügen</button>")}
function raw(){return page("Raw Data Explorer","Unveränderte CRM- und Crawl-Felder bleiben nachvollziehbar erhalten",`<div class="panel table-wrap"><table class="table"><tr><th>ID</th><th>Firmenname</th><th>Website</th><th>Rechtsform</th><th>Branche</th><th>NACE</th><th>Mitarbeiter</th><th>Ort</th><th>Raw Tags</th><th>Crawl</th><th>Aktualisiert</th></tr>${state.companies.map(c=>`<tr><td>${esc(c.company_id)}</td><td>${esc(c.company_name)}</td><td>${esc(c.website_url)}</td><td>${esc(c.legal_form)}</td><td>${esc(c.industry)}</td><td>${esc(c.nace_code)}</td><td>${esc(c.employee_range)}</td><td>${esc(c.city)}</td><td>${esc(c.raw_tags.join(" | "))}</td><td>${badge(c.crawl_status)}</td><td>${esc(c.last_crawled_at)}</td></tr>`).join("")}</table></div>`)}
function tagsView(){const pairs=allTags();return page("Tag Explorer","Normalisierte Hersteller-, Technologie- und Geschäftsfeld-Tags",`<div class="grid grid-3">${Object.entries(TAG_MAP).map(([g,map])=>`<div class="panel"><h3>${g==="manufacturers"?"Hersteller":g==="technologies"?"Technologien":"Geschäftsfelder"}</h3>${Object.keys(map).map(t=>{const n=state.companies.filter(c=>c.tags[g].includes(t)).length;return `<div class="split" style="padding:8px 0;border-bottom:1px solid var(--line)"><span>${esc(t)}</span><b>${n}</b></div>`}).join("")}</div>`).join("")}</div><div class="panel" style="margin-top:14px"><h3>Evidence-Treffer</h3>${state.companies.flatMap(c=>c.evidence.map(e=>`<div class="list-item"><b>${esc(c.company_name)} · ${esc(e.term)}</b><div>${esc(e.evidence)}</div><small class="muted">${esc(e.source_url)} · Confidence ${Math.round(e.confidence*100)}%</small></div>`)).join("")||'<div class="empty">Noch keine Evidence vorhanden.</div>'}</div>`)}
function clusters(){return page("CRM Cluster","Automatisch berechnete Zielgruppen für Kampagnen und CRM-Segmente",`<div class="grid grid-2">${CLUSTERS.map(cl=>{const members=state.companies.filter(c=>matchClusters(c).includes(cl.name));return `<div class="panel"><div class="split"><h3>${esc(cl.name)}</h3>${badge(members.length+" Treffer")}</div><p class="muted">Kriterien: ${[...cl.all,...cl.any].join(" · ")||"keine"}</p>${members.map(c=>`<div class="list-item"><b>${esc(c.company_name)}</b><div>${tags(c).map(t=>`<span class="tag">${esc(t)}</span>`).join("")}</div></div>`).join("")||'<div class="empty">Keine passenden Unternehmen. Tags ergänzen oder crawlen.</div>'}</div>`}).join("")}</div>`,"<button class=\"btn green\" data-action=\"exportClusters\">Cluster exportieren</button>")}
function sales(){const rows=[...state.companies].sort((a,b)=>b.opportunity_score-a.opportunity_score);return page("Sales Intelligence","Vertriebspriorisierung auf Basis von CRM-Daten und Enrichment",`<div class="panel table-wrap"><table class="table"><tr><th>Unternehmen</th><th>Opportunity Score</th><th>Priorität</th><th>Umsatz</th><th>Empfehlung</th><th>Cluster</th></tr>${rows.map(c=>`<tr><td><b>${esc(c.company_name)}</b><div class="muted">${esc(c.industry)}</div></td><td><span class="score">${c.opportunity_score}</span>/100</td><td>${badge(c.priority)}</td><td>${Number(c.crm_revenue||0).toLocaleString("de-DE")} €</td><td>${esc(c.priority==="A"?"Account-Review und Kampagne priorisieren":c.priority==="B"?"Gezielte Herstellerkampagne vorbereiten":"Daten ergänzen und qualifizieren")}</td><td>${c.clusters.map(x=>`<span class="tag">${esc(x)}</span>`).join("")||"–"}</td></tr>`).join("")}</table></div>`)}
function tender(){const rows=state.companies.map(c=>({company_id:c.company_id,company_name:c.company_name,capabilities:[...c.tags.business_areas,...c.tags.technologies],tender_categories:c.tags.business_areas,signals:c.evidence.map(e=>e.term),embedding_ready_text:`${c.company_name}. ${c.industry}. ${tags(c).join(", ")}.`}));return page("Tender AI Context","Separater Kontext für semantische Suche und Tender-Matching",`<div class="panel"><p class="muted">Der Tender-Kontext wird getrennt vom Sales-Ergebnis exportiert. API-Schlüssel werden nicht exportiert.</p><div class="code">${esc(JSON.stringify(rows.slice(0,2),null,2))}</div></div>`,"<button class=\"btn green\" data-action=\"exportTender\">JSONL exportieren</button>")}
function azure(){const a=state.azure;const u=buildAzureUrl(a);return page("Azure AI Setup","Azure OpenAI-Verbindung für bidirektionale Analysen",`<div class="panel"><div class="alert warn"><b>Wichtig:</b> Der Endpoint darf nur der Ressourcen-Host sein. Die Anwendung verwendet ausschließlich den unten angezeigten URL-Builder.</div><div class="form-grid"><label>Azure OpenAI Endpoint<input id="azEndpoint" value="${esc(a.endpoint)}" placeholder="https://name.openai.azure.com"></label><label>Deployment-Name<input id="azDeployment" value="${esc(a.deployment)}" placeholder="GPT-Deployment"></label><label>API-Version<select id="azVersion"><option ${a.apiVersion==="2025-04-01-preview"?"selected":""}>2025-04-01-preview</option><option ${a.apiVersion==="2024-10-21"?"selected":""}>2024-10-21</option><option ${a.apiVersion==="2024-08-01-preview"?"selected":""}>2024-08-01-preview</option></select></label><label>API-Schlüssel<input id="azKey" type="password" value="${esc(a.apiKey)}" placeholder="Azure OpenAI API-Key"></label></div><div class="toolbar" style="margin-top:14px"><button class="btn" data-action="saveAzure">Speichern</button><button class="btn primary" data-action="testAzure">Verbindung testen</button><button class="btn" data-action="downloadLog">Logfile herunterladen</button>${badge(a.status.state==="ok"?"Azure verbunden":a.status.state==="error"?"Azure Fehler":"Nicht getestet")}</div><div class="alert ${a.status.state==="ok"?"ok":a.status.state==="error"?"err":"warn"}">${esc(a.status.message||"Noch kein Verbindungstest ausgeführt.")}</div><h3>Effektive Request-URL</h3><div class="code">${esc(u)}</div><p class="muted">Bei direktem Öffnen über file:// kann Azure den Browseraufruf wegen CORS blockieren. Ein solcher Fehler wird separat geloggt. Die URL darf aber niemals doppelt aufgebaut werden.</p></div>`)}
function sources(){const s=state.settings;const rows=s.crawlPortals.map((p,i)=>`<tr><td style="text-align:center"><input type="checkbox" data-portal-enabled="${i}" ${p.enabled?"checked":""}></td><td><input class="search" data-portal-name="${i}" value="${esc(p.name)}"></td><td>${p.type==="website"?'<span class="muted">nutzt Firmen-Website</span>':`<input class="search" style="min-width:340px" data-portal-url="${i}" value="${esc(p.url)}">`}</td><td>${badge(p.type)}</td><td><button class="btn danger" data-portal-del="${i}" ${p.id==="website"?"disabled":""}>Entfernen</button></td></tr>`).join("");return page("Quellen & Crawling","Global festlegen, welche Portale gecrawlt werden – gilt für alle Unternehmen und neue Ausschreibungen",`<div class="panel"><div class="alert warn">Platzhalter in URL-Vorlagen: <b>{q}</b> = Firmenname, <b>{domain}</b> = Website-Domain. Typ <b>website</b> nutzt direkt die hinterlegte Unternehmens-Website.</div><div class="table-wrap"><table class="table"><tr><th>Aktiv</th><th>Portal</th><th>URL-Vorlage</th><th>Typ</th><th></th></tr>${rows}</table></div><div class="toolbar" style="margin-top:12px"><button class="btn" data-action="addPortal">+ Portal hinzufügen</button><button class="btn primary" data-action="saveSources">Speichern</button></div></div><div class="panel"><h3>CORS-Proxy (optional)</h3><div class="form-grid"><label class="full">Proxy-Präfix für Crawling<input id="setProxy" value="${esc(s.corsProxy||"")}" placeholder="https://mein-proxy/?url="></label></div><p class="muted">Direkte Website-Aufrufe aus <code>file://</code> blockiert der Browser meist per CORS. Zwei Auswege: den Browser mit <code>--disable-web-security</code> starten (siehe README) oder hier ein Proxy-Präfix hinterlegen, an das die Ziel-URL angehängt wird. Der Proxy sieht die gecrawlten URLs – nur vertrauenswürdige Proxys nutzen.</p><div class="toolbar"><button class="btn primary" data-action="saveSources">Speichern</button></div></div>`)}
function diagnostics(){return page("Diagnose & Tests","Lokale Unit Tests und optionaler echter Azure-Live-Test",`<div class="toolbar"><button class="btn primary" data-action="runTests">Unit Tests ausführen</button><button class="btn" data-action="runAzureTest">Tests + Azure Live-Test</button><button class="btn" data-action="downloadLog">Logfile herunterladen</button><button class="btn danger" data-action="clearLog">Log löschen</button></div><div id="testResults" class="panel" style="margin-top:14px">${state.testResults||'<div class="empty">Noch keine Tests ausgeführt.</div>'}</div><div class="panel"><h3>Log</h3><div class="code">${esc(logLines.join("\n")||"Noch keine Logeinträge.")}</div></div>`)}
function buildAzureUrl(raw){let ep=String(raw?.endpoint||"").trim();if(!ep)return"";if(!/^https?:\/\//i.test(ep))ep="https://"+ep;let base;try{base=new URL(ep).origin}catch(e){base=ep.replace(/\/openai\/.*$/i,"").replace(/[?#].*$/,"").replace(/\/+$/,"")}let dep=String(raw?.deployment||"").trim().replace(/^.*\/deployments\//i,"").split("/")[0];let ver=String(raw?.apiVersion||"").trim();if(!/^\d{4}-\d{2}-\d{2}(?:-preview)?$/.test(ver))ver="2025-04-01-preview";return dep?`${base}/openai/deployments/${encodeURIComponent(dep)}/chat/completions?api-version=${encodeURIComponent(ver)}`:""}
function validateAzureUrl(url){const e=[];if((url.match(/\/openai\/deployments\//g)||[]).length!==1)e.push("Deployment-Pfad muss genau einmal vorkommen");if((url.match(/\/chat\/completions/g)||[]).length!==1)e.push("Chat-Completion-Pfad muss genau einmal vorkommen");if(url.includes("/openai/responses"))e.push("Responses-Pfad ist nicht zulässig");if(/chat\/completions[^?#]*\/openai\//i.test(url))e.push("Nach chat/completions folgt ein weiterer Azure-Pfad");if(e.length)throw new Error(e.join("; "));return true}
function log(level,event,data={}){const safe=Object.assign({},data);delete safe.apiKey;delete safe.key;delete safe.apikey;delete safe["api-key"];const line=new Date().toISOString()+" ["+level+"] "+event+" "+JSON.stringify(safe);logLines.push(line);if(logLines.length>500)logLines.shift();saveLog();return line}
async function azureChat(messages,{maxTokens=800,temperature=0,jsonMode=false}={}){const a=state.azure,url=buildAzureUrl(a);if(!url)throw new Error("Azure-Konfiguration unvollständig");validateAzureUrl(url);log("INFO","azure_request_prepared",{url,jsonMode});let useCompletionTokens=false,dropTemp=false,dropJson=false;for(let attempt=0;attempt<5;attempt++){const body={messages};if(useCompletionTokens)body.max_completion_tokens=maxTokens;else body.max_tokens=maxTokens;if(!dropTemp&&temperature!=null)body.temperature=temperature;if(jsonMode&&!dropJson)body.response_format={type:"json_object"};let r;try{r=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json","api-key":a.apiKey},body:JSON.stringify(body)})}catch(e){log("ERROR","azure_connection_failed",Object.assign({message:e.message||String(e)},azureCtx()));throw new Error("Netzwerk-/CORS-Fehler: "+(e.message||e))}const text=await r.text();if(r.ok){let content="";try{const j=JSON.parse(text);content=(j.choices&&j.choices[0]&&j.choices[0].message&&j.choices[0].message.content)||""}catch(e){content=text}log("INFO","azure_connection_succeeded",{status:r.status,url,params:{tokenParam:useCompletionTokens?"max_completion_tokens":"max_tokens",temperature:dropTemp?"default":temperature}});return content}const d=text.toLowerCase();if(r.status===400){if(!useCompletionTokens&&/max_tokens/.test(d)&&(/max_completion_tokens/.test(d)||/not supported|unsupported/.test(d))){log("INFO","azure_retry_max_completion_tokens",{});useCompletionTokens=true;continue}if(useCompletionTokens&&/max_completion_tokens/.test(d)&&/not supported|unsupported|unknown|unrecognized/.test(d)){useCompletionTokens=false;continue}if(!dropTemp&&/temperature/.test(d)&&/not support|unsupported|does not support|only.*(default|1)/.test(d)){log("INFO","azure_retry_drop_temperature",{});dropTemp=true;continue}if(jsonMode&&!dropJson&&/response_format|json_object|json mode/.test(d)&&/not support|unsupported|does not support|unknown|unrecognized|invalid|cannot/.test(d)){log("INFO","azure_retry_drop_response_format",{});dropJson=true;continue}}log("ERROR","azure_http_error",Object.assign({status:r.status,detail:text.slice(0,300),attempt:attempt+1,tokenParam:useCompletionTokens?"max_completion_tokens":"max_tokens"},azureCtx()));const hint=r.status===401?" — API-Schlüssel bzw. Endpoint/Region prüfen (der Schlüssel muss zur Azure-Ressource des Endpoints gehören)":r.status===404?" — Deployment-Name prüfen":r.status===400?" — Parameter/API-Version prüfen":"";throw new Error(`Azure HTTP ${r.status}: ${text.slice(0,300)}${hint}`)}log("ERROR","azure_fallback_exhausted",{url});throw new Error("Azure-Anfrage schlägt auch nach Parameter-Fallback fehl.")}
async function testAzure(){const a=state.azure;if(!a.endpoint||!a.deployment||!a.apiKey){a.status={state:"error",message:"Endpoint, Deployment-Name und API-Schlüssel sind erforderlich."};save();render();return}try{const out=await azureChat([{role:"system",content:"Antworte ausschließlich mit OK."},{role:"user",content:"Verbindungstest"}]);a.status={state:"ok",message:"Azure AI verbunden. Antwort: "+out.slice(0,100)};log("INFO","azure_test_ok",{})}catch(e){a.status={state:"error",message:e.message};log("ERROR","azure_test_failed",{message:e.message,url:buildAzureUrl(a)});}save();render()}
function formCompany(c={}){const x=normalizeCompany(c);return `<div class="modal-box"><div class="modal-head"><h2>${c.company_id?"Unternehmen bearbeiten":"Unternehmen hinzufügen"}</h2><button class="btn" data-close>×</button></div><div class="form-grid"><label>Company ID<input id="f_id" value="${esc(x.company_id)}"></label><label>Firmenname<input id="f_name" value="${esc(x.company_name)}"></label><label>Website<input id="f_url" value="${esc(x.website_url)}"></label><label>Rechtsform<input id="f_legal" value="${esc(x.legal_form)}"></label><label>Branche<input id="f_industry" value="${esc(x.industry)}"></label><label>NACE-Code<input id="f_nace" value="${esc(x.nace_code)}"></label><label>NACE-Bezeichnung<input id="f_nacelabel" value="${esc(x.nace_label)}"></label><label>Mitarbeiterklasse<input id="f_emp" value="${esc(x.employee_range)}"></label><label>Ort<input id="f_city" value="${esc(x.city)}"></label><label>Land<input id="f_country" value="${esc(x.country)}"></label><label>CRM-Umsatz<input id="f_rev" type="number" value="${Number(x.crm_revenue||0)}"></label><label>Mitarbeiterzahl<input id="f_emps" value="${esc((x.firmographics||{}).employees||"")}"></label><label>Niederlassungen<input id="f_locs" value="${esc((x.firmographics||{}).locations||"")}"></label><label>Gründungsjahr<input id="f_founded" value="${esc((x.firmographics||{}).founded_year||"")}"></label><label>Priorität<select id="f_prio">${["A","B","C","D"].map(p=>`<option ${x.priority===p?"selected":""}>${p}</option>`).join("")}</select></label><label class="full">Tags / Suchbegriffe (Komma getrennt)<input id="f_tags" value="${esc(x.raw_tags.join(", "))}"></label><label class="full">Website-/Quelltext für KI (optional)<textarea id="f_srctext" placeholder="Text von der Website hier einfügen, falls automatisches Crawling per CORS blockiert wird">${esc(x.source_text)}</textarea></label><label class="full">Notizen<textarea id="f_notes">${esc(x.notes)}</textarea></label></div><div class="toolbar" style="margin-top:14px"><button class="btn primary" data-save-company="${esc(x.company_id)}">Speichern</button><button class="btn" data-close>Abbrechen</button></div></div>`}
function openCompany(id=""){const c=id?state.companies.find(x=>x.company_id===id):{};const m=document.querySelector("#modal");m.innerHTML=formCompany(c);m.classList.remove("hidden");m.querySelectorAll("[data-close]").forEach(x=>x.onclick=closeModal);m.querySelector("[data-save-company]").onclick=()=>saveCompany(id)}
function saveCompany(oldId){const v=id=>document.querySelector("#"+id)?.value||"";const c=normalizeCompany({company_id:v("f_id").trim()||"CRM-"+Date.now(),company_name:v("f_name").trim()||"Unbenannt",website_url:v("f_url").trim(),legal_form:v("f_legal").trim(),industry:v("f_industry").trim(),nace_code:v("f_nace").trim(),nace_label:v("f_nacelabel").trim(),employee_range:v("f_emp").trim(),city:v("f_city").trim(),country:v("f_country").trim(),crm_revenue:Number(v("f_rev"))||0,priority:v("f_prio"),raw_tags:v("f_tags").split(",").map(x=>x.trim()).filter(Boolean),notes:v("f_notes"),source_text:v("f_srctext")});const i=state.companies.findIndex(x=>x.company_id===oldId);const base=i>=0?(state.companies[i].firmographics||{}):{};c.firmographics=Object.assign({},base,{employees:v("f_emps").trim(),locations:v("f_locs").trim(),founded_year:v("f_founded").trim()});if(i>=0){c.tags=state.companies[i].tags;c.evidence=state.companies[i].evidence;c.crawl_status=state.companies[i].crawl_status;c.opportunity_score=state.companies[i].opportunity_score;c.clusters=state.companies[i].clusters;c.ai_summary=state.companies[i].ai_summary;c.ai_potential=state.companies[i].ai_potential;state.companies[i]=c}else state.companies.push(c);save();closeModal();render();toast("Unternehmen gespeichert")}
function closeModal(){document.querySelector("#modal").classList.add("hidden")}
function exportFile(name,content,type="application/json"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function importData(file){const reader=new FileReader();reader.onload=()=>{try{let data=JSON.parse(reader.result);if(!Array.isArray(data))data=data.companies||[];state.companies=data.map(normalizeCompany);save();render();toast("Daten importiert")}catch(e){toast("Importfehler: "+e.message)}};reader.readAsText(file)}
function csv(rows){return rows.map(r=>r.map(v=>`"${String(v??"").replace(/"/g,'""')}"`).join(";")).join("\n")}
function exportClusters(){const rows=[["cluster_id","cluster_name","company_id","company_name","matched_tags"]];CLUSTERS.forEach(cl=>state.companies.filter(c=>matchClusters(c).includes(cl.name)).forEach(c=>rows.push([cl.id,cl.name,c.company_id,c.company_name,tags(c).join("|")])));exportFile("crm_clusters.csv",csv(rows),"text/csv")}
function exportTender(){const rows=state.companies.map(c=>JSON.stringify({company_id:c.company_id,company_name:c.company_name,capability_profile:[...c.tags.business_areas,...c.tags.technologies],tender_categories:c.tags.business_areas,relevance_signals:c.evidence.map(e=>e.term),embedding_ready_text:`${c.company_name}. ${c.industry}. ${tags(c).join(", ")}.`})).join("\n");exportFile("tender_ai_context.jsonl",rows,"application/x-ndjson")}
function backup(){const x=JSON.parse(JSON.stringify(state));x.azure.apiKey="";exportFile("also-crm-backup.json",JSON.stringify(x,null,2))}
function runTests(live=false){const results=[];function t(name,fn){try{fn();results.push({name,ok:true,msg:"OK"})}catch(e){results.push({name,ok:false,msg:e.message})}}t("URL normalisiert",()=>{const u=buildAzureUrl({endpoint:"https://x.openai.azure.com/openai/responses?api-version=bad",deployment:"D",apiVersion:"0205-04-01-preview"});if(u!=="https://x.openai.azure.com/openai/deployments/D/chat/completions?api-version=2025-04-01-preview")throw Error(u)});t("URL nicht doppelt",()=>{const u=buildAzureUrl({endpoint:"https://x.openai.azure.com/openai/deployments/D/chat/completions?api-version=2025-04-01-preview",deployment:"D",apiVersion:"2025-04-01-preview"});validateAzureUrl(u)});t("Crawling erzeugt Tags",()=>{const c=normalizeCompany({company_name:"Test Microsoft Azure",raw_tags:[]});crawlCompany(c);if(!tags(c).length)throw Error("Keine Tags")});t("Cluster berechenbar",()=>{const c=normalizeCompany({company_name:"Test",tags:{manufacturers:["Microsoft"],technologies:["Azure"],business_areas:["Cloud Services"]}});if(!matchClusters(c).length)throw Error("Kein Cluster")});t("Log schützt Schlüssel",()=>{const before=logLines.length;log("INFO","secret_test",{apiKey:"DO_NOT_LOG"});if(logLines.slice(before).join("").includes("DO_NOT_LOG"))throw Error("API-Key geloggt")});if(live){return (async()=>{try{await testAzure();results.push({name:"Azure Live-Verbindung",ok:state.azure.status.state==="ok",msg:state.azure.status.message})}catch(e){results.push({name:"Azure Live-Verbindung",ok:false,msg:e.message})}showTests(results)})()}showTests(results)}
function showTests(rs){state.testResults=rs.map(r=>`<div class="list-item">${r.ok?"✅":"❌"} <b>${esc(r.name)}</b><div class="muted">${esc(r.msg)}</div></div>`).join("");log("INFO","unit_tests_completed",{passed:rs.filter(x=>x.ok).length,failed:rs.filter(x=>!x.ok).length});render()}
function render(){const main=document.querySelector("#main");main.innerHTML=({dashboard,companies,raw,tags:tagsView,clusters,sales,tender,sources,azure,diagnostics}[view]||dashboard)();document.querySelectorAll(".nav").forEach(n=>n.classList.toggle("active",n.dataset.view===view));bind()}
function bind(){document.querySelectorAll("[data-view]").forEach(n=>n.onclick=()=>{view=n.dataset.view;render()});document.querySelectorAll('[data-action="add"]').forEach(n=>n.onclick=()=>openCompany());document.querySelectorAll('[data-action="crawlAll"]').forEach(n=>n.onclick=()=>{state.companies.forEach(c=>crawlCompany(c));render();toast("Alle Unternehmen gecrawlt")});document.querySelectorAll("[data-crawl]").forEach(n=>n.onclick=()=>{const c=state.companies.find(x=>x.company_id===n.dataset.crawl);if(c){crawlCompany(c);render();toast("Crawling abgeschlossen")}});document.querySelectorAll("[data-edit]").forEach(n=>n.onclick=()=>openCompany(n.dataset.edit));document.querySelectorAll("[data-delete]").forEach(n=>n.onclick=()=>{state.companies=state.companies.filter(c=>c.company_id!==n.dataset.delete);save();render();toast("Unternehmen gelöscht")});document.querySelectorAll('[data-action="backup"]').forEach(n=>n.onclick=backup);document.querySelectorAll('[data-action="import"]').forEach(n=>n.onclick=()=>document.querySelector("#fileImport").click());document.querySelector("#fileImport").onchange=e=>importData(e.target.files[0]);document.querySelectorAll('[data-action="exportClusters"]').forEach(n=>n.onclick=exportClusters);document.querySelectorAll('[data-action="exportTender"]').forEach(n=>n.onclick=exportTender);document.querySelectorAll('[data-action="saveAzure"]').forEach(n=>n.onclick=()=>{state.azure.endpoint=document.querySelector("#azEndpoint").value.trim();state.azure.deployment=document.querySelector("#azDeployment").value.trim();state.azure.apiVersion=document.querySelector("#azVersion").value;state.azure.apiKey=document.querySelector("#azKey").value.trim();save();render();toast("Azure-Konfiguration gespeichert")});document.querySelectorAll('[data-action="testAzure"]').forEach(n=>n.onclick=()=>{state.azure.endpoint=document.querySelector("#azEndpoint").value.trim();state.azure.deployment=document.querySelector("#azDeployment").value.trim();state.azure.apiVersion=document.querySelector("#azVersion").value;state.azure.apiKey=document.querySelector("#azKey").value.trim();save();testAzure()});document.querySelectorAll('[data-action="runTests"]').forEach(n=>n.onclick=()=>runTests(false));document.querySelectorAll('[data-action="runAzureTest"]').forEach(n=>n.onclick=()=>runTests(true));document.querySelectorAll('[data-action="downloadLog"]').forEach(n=>n.onclick=()=>{log("INFO","log_exported",{lines:logLines.length});exportFile("also-diagnostics-"+new Date().toISOString().replace(/[:.]/g,"-")+".log",logHeader()+logLines.join("\n")+"\n","text/plain");toast("Logfile heruntergeladen")});document.querySelectorAll('[data-action="clearLog"]').forEach(n=>n.onclick=()=>{logLines=[];saveLog();log("INFO","log_cleared",{});render();toast("Log gelöscht")});document.querySelectorAll("[data-ai]").forEach(n=>n.onclick=async()=>{const c=state.companies.find(x=>x.company_id===n.dataset.ai);if(!c)return;n.disabled=true;n.textContent="… analysiert";toast("KI-Analyse läuft …");try{const r=await analyzeCompanyAI(c);render();toast("KI-Analyse fertig ("+r.sources.length+" Quelle(n))")}catch(e){log("ERROR","ai_analysis_failed",Object.assign({company:c.company_id,message:e.message},azureCtx()));crawlCompany(c);setAIResult(c);render();toast("KI fehlgeschlagen – Keyword-Fallback: "+e.message)}});document.querySelectorAll('[data-action="crawlAllAI"]').forEach(n=>n.onclick=async()=>{n.disabled=true;toast("KI-Analyse aller Unternehmen läuft …");let ok=0,fb=0;for(const c of state.companies){try{await analyzeCompanyAI(c);ok++}catch(e){log("ERROR","ai_analysis_failed",{company:c.company_id,message:e.message});crawlCompany(c);fb++}}render();toast("KI-Analyse: "+ok+" ok, "+fb+" Fallback")});document.querySelectorAll('[data-action="addPortal"]').forEach(n=>n.onclick=()=>{state.settings.crawlPortals.push({id:"portal-"+Date.now(),name:"Neues Portal",type:"search",url:"https://beispiel.de/suche?q={q}",enabled:false});save();render()});document.querySelectorAll("[data-portal-del]").forEach(n=>n.onclick=()=>{const i=Number(n.dataset.portalDel);state.settings.crawlPortals.splice(i,1);save();render();toast("Portal entfernt")});document.querySelectorAll('[data-action="saveSources"]').forEach(n=>n.onclick=()=>{state.settings.crawlPortals.forEach((p,i)=>{const en=document.querySelector('[data-portal-enabled="'+i+'"]');const nm=document.querySelector('[data-portal-name="'+i+'"]');const ur=document.querySelector('[data-portal-url="'+i+'"]');if(en)p.enabled=en.checked;if(nm)p.name=nm.value.trim()||p.name;if(ur)p.url=ur.value.trim()});const px=document.querySelector("#setProxy");if(px)state.settings.corsProxy=px.value.trim();save();render();toast("Quellen gespeichert")});document.querySelectorAll('[data-action="closeAI"]').forEach(n=>n.onclick=()=>{state.aiResult=null;save();render()})}
window.addEventListener("error",e=>{try{log("ERROR","window_error",{message:e.message||String(e),source:e.filename||"",line:e.lineno||0,col:e.colno||0})}catch(_){}});window.addEventListener("unhandledrejection",e=>{try{const r=e&&e.reason;log("ERROR","unhandled_rejection",{message:r&&r.message?r.message:String(r)})}catch(_){}});log("INFO","app_started",{protocol:location.protocol});if(!state.companies.length){state.companies=[];save()}render();
})();